package org.simplejavamail.api.email;

import jakarta.activation.DataSource;
import lombok.extern.slf4j.Slf4j;
import lombok.val;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import static org.simplejavamail.internal.util.MiscUtil.normalizeNewlines;

/**
 * Implements the selective value comparisons documented by {@link Email#equals(Object)} and {@link AttachmentResource#equals(Object)}.
 * The equals code was introduced to analyze JUnit test errors.
 * <p>
 * The initial code was generated by IntelliJ and expanded for recipient values and DataSource metadata. This helper does not define
 * complete object-state, content-byte or sending-equivalence comparison.
 */
@SuppressWarnings("SimplifiableIfStatement")
@Slf4j
public final class EqualsHelper {

    @SuppressWarnings("WeakerAccess")
    public static boolean equalsEmail(final Email email1, final Email email2) {
        if (!fieldIsEqual(email1.getFromRecipient(), email2.getFromRecipient(), "fromRecipient")) {
            return false;
        }
        if (!fieldIsEqual(email1.getId(), email2.getId(), "id")) {
            return false;
        }
        if (!fieldIsEqual(email1.getSentDate(), email2.getSentDate(), "sendDate")) {
            return false;
        }
        if (!isEqualUnorderedList("ReplyTo recipients", email1.getReplyToRecipients(), email2.getReplyToRecipients())) {
            return false;
        }
        if (!fieldIsEqual(email1.getBounceToRecipient(), email2.getBounceToRecipient(), "bounceToRecipient")) {
            return false;
        }
        if (!fieldIsEqual(email1.getPlainText(), email2.getPlainText(), "plainText")) {
            return false;
        }
        if (!fieldIsEqual(email1.getCalendarText(), email2.getCalendarText(), "calendarText")) {
            return false;
        }
        if (!fieldIsEqual(email1.getCalendarMethod(), email2.getCalendarMethod(), "calendarMethod")) {
            return false;
        }
        if (!fieldIsEqual(effectiveContentTransferEncoding(email1), effectiveContentTransferEncoding(email2), "contentTransferEncoding")) {
            return false;
        }
        if (!fieldIsEqual(email1.getPlainTextContentTransferEncoding(), email2.getPlainTextContentTransferEncoding(), "plainTextContentTransferEncoding")) {
            return false;
        }
        if (!fieldIsEqual(email1.getHTMLTextContentTransferEncoding(), email2.getHTMLTextContentTransferEncoding(), "htmlTextContentTransferEncoding")) {
            return false;
        }
        if (!fieldIsEqual(email1.getCalendarTextContentTransferEncoding(), email2.getCalendarTextContentTransferEncoding(), "calendarTextContentTransferEncoding")) {
            return false;
        }
        //noinspection SimplifiableConditionalExpression
        if (email1.getEmailToForward() != null ? email2.getEmailToForward() == null : email2.getEmailToForward() != null) {
            log.debug("Email unqual for emailToForward: {} vs {}", email1.getEmailToForward(), email2.getEmailToForward());
            return false;
        }
        if (email1.getHTMLText() != null ? !normalizeNewlines(email1.getHTMLText()).equals(normalizeNewlines(email2.getHTMLText())) : email2.getHTMLText() != null) {
            log.debug("Email unqual for HTML text: {} vs {}", email1.getHTMLText(), email2.getHTMLText());
            return false;
        }
        if (!fieldIsEqual(email1.getSubject(), email2.getSubject(), "subject")) {
            return false;
        }
        if (!isEqualUnorderedList("TO/CC/BCC recipients", email1.getRecipients(), email2.getRecipients())) {
            return false;
        }
        if (!isEqualUnorderedList("Override receivers", email1.getOverrideReceivers(), email2.getOverrideReceivers())) {
            return false;
        }
        if (!isEqualUnorderedList("embedded images", email1.getEmbeddedImages(), email2.getEmbeddedImages())) {
            return false;
        }
        if (!isEqualUnorderedList("attachments", email1.getAttachments(), email2.getAttachments())) {
            return false;
        }
        if (!email1.getHeaders().equals(email2.getHeaders())) {
            log.debug("Email unqual for headers: {} vs {}", email1.getHeaders(), email2.getHeaders());
            return false;
        }
        if (!Objects.equals(email1.getUseDispositionNotificationTo(), email2.getUseDispositionNotificationTo())) {
            log.debug("Email unqual for useDispositionNotificationTo: {} vs {}", email1.getUseDispositionNotificationTo(), email2.getUseDispositionNotificationTo());
            return false;
        }
        if (!Objects.equals(email1.getUseReturnReceiptTo(), email2.getUseReturnReceiptTo())) {
            log.debug("Email unqual for useReturnReceiptTo: {} vs {}", email1.getUseReturnReceiptTo(), email2.getUseReturnReceiptTo());
            return false;
        }
        if (!fieldIsEqual(email1.getDispositionNotificationToRecipients(), email2.getDispositionNotificationToRecipients(), "dispositionNotificationTo")) {
            return false;
        }
        if (!fieldIsEqual(email1.getDeliveryStatusNotification(), email2.getDeliveryStatusNotification(), "deliveryStatusNotification")) {
            return false;
        }
        if (!fieldIsEqual(email1.getDeliveryStatusReport(), email2.getDeliveryStatusReport(), "deliveryStatusReport")) {
            return false;
        }
        if (!fieldIsEqual(email1.getSendingToAcceptedRecipients(), email2.getSendingToAcceptedRecipients(), "sendingToAcceptedRecipients")) {
            return false;
        }
        if (email1.isTlsRequiredForOnwardDelivery() != email2.isTlsRequiredForOnwardDelivery()) {
            log.debug("Email unequal for tlsRequiredForOnwardDelivery: {} vs {}",
                    email1.isTlsRequiredForOnwardDelivery(), email2.isTlsRequiredForOnwardDelivery());
            return false;
        }
        if (!fieldIsEqual(email1.getOriginalSmimeDetails(), email2.getOriginalSmimeDetails(), "originalSmimeDetails")) {
            return false;
        }
        if (!fieldIsEqual(email1.getDkimConfig(), email2.getDkimConfig(), "dkimConfig")) {
            return false;
        }
        if (!fieldIsEqual(email1.getSmimeSigningConfig(), email2.getSmimeSigningConfig(), "smimeSigningConfig")) {
            return false;
        }
        if (!fieldIsEqual(email1.getSmimeEncryptionConfig(), email2.getSmimeEncryptionConfig(), "smimeEncryptionConfig")) {
            return false;
        }
        if (!fieldIsEqual(email1.getOpenPgpSigningConfig(), email2.getOpenPgpSigningConfig(), "openPgpSigningConfig")) {
            return false;
        }
        if (!fieldIsEqual(email1.getOpenPgpEncryptionConfig(), email2.getOpenPgpEncryptionConfig(), "openPgpEncryptionConfig")) {
            return false;
        }
        if (!fieldIsEqual(email1.getOriginalOpenPgpDetails(), email2.getOriginalOpenPgpDetails(), "originalOpenPgpDetails")) {
            return false;
        }
        return fieldIsEqual(email1.getReturnReceiptToRecipients(), email2.getReturnReceiptToRecipients(), "returnReceiptTo");
    }

    private static <T> boolean isEqualUnorderedList(final String fieldName, final List<T> values, final List<T> otherValues) {
        if (values.size() != otherValues.size()) {
            log.debug("Email unequal for {}: {} vs {}", fieldName, values, otherValues);
            return false;
        }
        // Keep order-insensitive equality, but let each occurrence satisfy only one counterpart.
        // Resource equality compares metadata; it must not read borrowed attachment or image content.
        final List<T> unmatchedValues = new ArrayList<>(values);
        for (final T otherValue : otherValues) {
            if (!unmatchedValues.remove(otherValue)) {
                log.debug("Email unequal for {}: {} vs {}", fieldName, values, otherValues);
                return false;
            }
        }
        return true;
    }

    private static ContentTransferEncoding effectiveContentTransferEncoding(final Email email) {
        return email.getContentTransferEncoding() != null ? email.getContentTransferEncoding() : ContentTransferEncoding.getDefault();
    }

    static boolean isEqualDataSource(@Nullable final DataSource a, @Nullable final DataSource b) {
        return (a == b) || (a != null && b != null &&
                fieldIsEqual(a.getName(), b.getName(), "name") &&
                fieldIsEqual(a.getContentType(), b.getContentType(), "contentType"));
    }

    private static boolean fieldIsEqual(final Object obj1, final Object obj2, final String name) {
        val isEqual = Objects.equals(obj1, obj2);
        if (!isEqual) log.debug("Email unqual for {}: {} vs {}", name, obj1, obj2);
        return isEqual;
    }
}
